def profile_digest(value):
    """The retained profile uses compact sorted UTF-8 JSON, unlike product hashes."""
    return digest(json.dumps(value, sort_keys=True, separators=(",", ":"),
                             ensure_ascii=False, allow_nan=False).encode())


def admit(graph, supplied):
    """Bind a reviewed map to the full original source-page occurrences."""
    required = {"version", "profile", "graph_sha256", "document", "review", "reading"}
    fields(supplied, required, required)
    profile = PROFILES.get(supplied["profile"]) if isinstance(supplied["profile"], str) else None
    if (supplied["version"] != "source-statement-cells.v1" or profile is None
            or supplied["document"] != profile["document"]):
        raise ValueError("Unsupported source statement cell profile or document")
    if supplied["graph_sha256"] != digest(graph):
        raise ValueError("Statement cell source graph changed")
    review(supplied["review"])
    if profile_digest(supplied["reading"]) != profile["reading"]:
        raise ValueError("Statement cell reading differs from the reviewed source profile")
    units = graph["units"]
    if len({u["id"] for u in units}) != len(units):
        raise ValueError("Duplicate statement source occurrence identity")
    selected = sorted((u for u in units if u["document"] == profile["document"] and u["page"] in profile["pages"]),
                      key=lambda u: (u["page"], u["order"], u["id"]))
    if (len(selected) != profile["occurrences"] or any(not u["visible"] or u["source_sha256"] != profile["source"] for u in selected)
            or profile_digest(selected) != profile["pages_digest"]):
        raise ValueError("Statement cell original pages or geometry changed")
    body = {"version": "admitted-statement-cells.v1", "profile": supplied["profile"],
            "graph_sha256": digest(graph), "input_sha256": digest(supplied),
            "document": profile["document"], "source_sha256": profile["source"],
            "page_occurrences_sha256": profile["pages_digest"], "reading_sha256": profile["reading"],
            "review": deepcopy(supplied["review"]), "reading": deepcopy(supplied["reading"])}
    return {**body, "sha256": digest(body)}


def explain(admitted):
    """Expose the consumed source reading while retaining its qualifications."""
    if admitted["sha256"] != digest({k: v for k, v in admitted.items() if k != "sha256"}):
        raise ValueError("Admitted statement cell evidence changed")
    reading = admitted["reading"]
    profile = PROFILES[admitted["profile"]]
    reading_fields = profile.get("reading_fields")
    if reading_fields is None:
        reading_fields = (profile["table_field"], "rows")
    context = reading.get("source_context")
    if context is None:
        context = {"unaudited_source": True, "source_authenticity": reading["source_authenticity"],
                   "independent_financial_review": reading["independent_review"],
                   "incorporation_status": "UNRESOLVED"}
    return {"profile": admitted["profile"], "document": admitted["document"],
            "source_sha256": admitted["source_sha256"], "evidence_sha256": admitted["sha256"],
            "reading_sha256": admitted["reading_sha256"], "origin": "SUPPLIED_DEVELOPMENT_READING",
            "review": deepcopy(admitted["review"]), "source_context": deepcopy(context),
            **{key: deepcopy(reading[key]) for key in reading_fields},
            "consumed": True, "independent_financial_acceptance": False,
            "legal_dependency_resolution": "UNCHANGED",
            "limit": "Exact reviewed source edition and geometry; supplied statement interpretation, not a general table parser or independent audit"}
